import { createRequire } from 'node:module';
import { isBot, findBotMatches } from 'isbot';

const { version } = createRequire(import.meta.url)('isbot/package.json');
const PRIVATE_TOOLS = new Set(['visitor.search_events', 'visitor.get_session_events']);
const LIMITATIONS = [
  'User-Agent is self-reported. A match indicates automation, not verified operator identity or malicious intent.',
  'No match and recorded bot=false do not verify a human. Network ownership and bot challenges were not checked.',
  'Page views, scroll progress and engaged time can be generated by automation. Location is not identity.',
  'Session statistics cover only returned events. Pagination and filters can omit other session activity.',
];

export function analyzeVisitorTraffic(toolName, result, principal) {
  if (!PRIVATE_TOOLS.has(toolName)) return result;
  if (String(principal?.role || '').toUpperCase() !== 'ADMIN') {
    throw new Error('Administrator access is required for visitor diagnostics');
  }
  if (!Array.isArray(result?.items) || result.items.length > 100) {
    throw new Error('Visitor event response is invalid or exceeds the diagnostic page limit');
  }
  const sessions = new Map();
  const counts = { automationIndicated: 0, undetermined: 0, storedFlagConflicts: 0, missingUserAgent: 0 };
  const items = result.items.map((item, index) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) throw new Error('Invalid visitor event');
    const raw = typeof item.userAgent === 'string' ? item.userAgent.trim() : '';
    const ua = raw.slice(0, 8192);
    const detected = Boolean(ua) && isBot(ua);
    const verdict = detected ? 'AUTOMATION_INDICATED' : 'UNDETERMINED';
    const conflict = detected && item.bot === false;
    counts[detected ? 'automationIndicated' : 'undetermined']++;
    if (conflict) counts.storedFlagConflicts++;
    if (!ua) counts.missingUserAgent++;
    const key = item.sessionId || `missing-session-${index}`;
    if (!sessions.has(key)) sessions.set(key, { sessionId: item.sessionId || null, events: 0,
      automationIndicated: 0, eventTypes: {}, ips: new Set(), times: [], readTimes: [], engagedSeconds: [] });
    const session = sessions.get(key);
    session.events++;
    if (detected) session.automationIndicated++;
    const event = typeof item.eventName === 'string' ? item.eventName : 'unknown';
    Object.defineProperty(session.eventTypes, event, { value: (Object.hasOwn(session.eventTypes, event)
      ? session.eventTypes[event] : 0) + 1, enumerable: true, configurable: true });
    if (item.ipAddress) session.ips.add(item.ipAddress);
    const timestamp = Date.parse(item.eventTime);
    if (Number.isFinite(timestamp)) {
      session.times.push(timestamp);
      if (event === 'read_progress') session.readTimes.push(timestamp);
    }
    const engaged = item.properties?.engagedSeconds;
    if (event === 'engaged_time' && typeof engaged === 'number' && Number.isFinite(engaged) && engaged >= 0) {
      session.engagedSeconds.push(engaged);
    }
    return { ...item, automationEvidence: { verdict, basis: ua ? 'USER_AGENT_PATTERN' : 'MISSING_USER_AGENT',
      matches: detected ? findBotMatches(ua).slice(0, 10).map(match => match.slice(0, 120)) : [],
      storedFlagDisagrees: conflict, userAgentTruncated: raw.length > ua.length, operatorVerified: false } };
  });
  const total = result.page?.totalElements;
  const knownTotal = Number.isSafeInteger(total) && total >= 0;
  const complete = result.page?.number === 0 && knownTotal && items.length === total;
  return { ...result, items, trafficAnalysis: {
    policyVersion: 'visitor-evidence-v1', detector: `isbot@${version}`,
    scope: 'RETURNED_EVENTS_ONLY', sampledEvents: items.length,
    windowTotalEvents: knownTotal ? total : null, completeWindow: complete,
    verdict: items.length > 0 && counts.automationIndicated === items.length ? 'AUTOMATION_INDICATED'
      : counts.automationIndicated > 0 ? 'MIXED_OR_INCOMPLETE_EVIDENCE' : 'UNDETERMINED',
    counts, operatorVerification: 'NOT_PERFORMED', humanVerification: 'NOT_PERFORMED',
    sessions: [...sessions.values()].map(session => ({ sessionId: session.sessionId, events: session.events,
      automationIndicated: session.automationIndicated, eventTypes: session.eventTypes,
      distinctIpCount: session.ips.size,
      firstEventAt: session.times.length ? new Date(Math.min(...session.times)).toISOString() : null,
      lastEventAt: session.times.length ? new Date(Math.max(...session.times)).toISOString() : null,
      observedSpanMs: span(session.times), readProgressSpanMs: span(session.readTimes),
      reportedEngagedSeconds: session.engagedSeconds })),
    limitations: LIMITATIONS,
    nextAction: complete ? 'REVIEW_EVIDENCE_AND_UNCERTAINTY' : 'READ_NEXT_PAGE_WITH_SAME_FILTERS_AND_FIXED_FROM_TO',
  } };
}

function span(times) { return times.length > 1 ? Math.max(...times) - Math.min(...times) : null; }
